import{_ as a,o as n,c as t,a3 as i}from"./chunks/framework.DLTBzH1I.js";const g=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),o={name:"explanation/decisions.md"};function s(r,e,c,d,l,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite — the decisions that shape mimus, the alternatives rejected, and the consequence each carries.</p><h2 id="no-evidence-no-finding" tabindex="-1">No evidence, no finding <a class="header-anchor" href="#no-evidence-no-finding" aria-label="Permalink to &quot;No evidence, no finding&quot;">​</a></h2><p><strong>Decision:</strong> every violation must cite claim + proof (+ optional fix). A checker that cannot produce evidence emits nothing.</p><p><strong>Alternatives:</strong> best-effort heuristics that flag <em>suspected</em> issues (false positives kill a critic faster than false negatives); LLM-judged everything (non-deterministic, ungateable, expensive).</p><p><strong>Consequence:</strong> the mechanical tier is conservative — command claims need a binary allowlist, ambiguous spans classify as prose, bad rule regexes are silence + a doctor complaint. Coverage is traded for trust.</p><h2 id="the-semantic-tier-can-never-gate" tabindex="-1">The semantic tier can never gate <a class="header-anchor" href="#the-semantic-tier-can-never-gate" aria-label="Permalink to &quot;The semantic tier can never gate&quot;">​</a></h2><p><strong>Decision:</strong> the <code>acp</code> checker reports <code>warn</code>-tier findings only; <code>mimus check</code>&#39;s exit code is decided by mechanical + graph alone.</p><p><strong>Alternatives:</strong> let the agent vote in CI (non-determinism makes flaky gates; a provider outage would block merges); drop semantic entirely (behavior claims — the majority of real doc rot — go unchecked).</p><p><strong>Consequence:</strong> semantic findings inform humans and agents but can never break a build. Its intake is the graph tier&#39;s fuzzy residue — pre-bucketed candidate pairs — not the raw claim set, so the agent never scans every claim.</p><h2 id="rules-are-data-not-code" tabindex="-1">Rules are data, not code <a class="header-anchor" href="#rules-are-data-not-code" aria-label="Permalink to &quot;Rules are data, not code&quot;">​</a></h2><p><strong>Decision:</strong> conventions live in <code>rules/*.toml</code> — regex, message, severity — interpreted by one checker.</p><p><strong>Alternatives:</strong> per-convention checker crates (adapter sprawl for what is fundamentally a pattern match); hard-coded checks in Rust (every org convention becomes a release).</p><p><strong>Consequence:</strong> &quot;dispatch via roles, never <code>kind ==</code>&quot; is a file a repo adds in a diff. The regex engine is the only thing that can be wrong, and its failure mode is silence, not a crash.</p><h2 id="claims-fold-into-batches-debounced" tabindex="-1">Claims fold into batches, debounced <a class="header-anchor" href="#claims-fold-into-batches-debounced" aria-label="Permalink to &quot;Claims fold into batches, debounced&quot;">​</a></h2><p><strong>Decision:</strong> semantic-tier prompts batch claims and pace calls; mechanical findings short-circuit before any agent is invoked.</p><p><strong>Alternatives:</strong> one prompt per claim (provider spend and rate limits scale with doc size); synchronous agent calls inside the gate (latency + flakiness in CI).</p><p><strong>Consequence:</strong> the critic is polite to providers by construction, and <code>--diff</code> scopes both extraction and graph findings to what actually changed.</p>',18)])])}const m=a(o,[["render",s]]);export{g as __pageData,m as default};
